-- handmatige boekseed voor de boekentabel (in totaal 40 boeken).

INSERT INTO books (
    title,
    author,
    isbn,
    binding,
    language,
    genre,
    summary,
    price,
    price_cents,
    delivery,
    stock
) VALUES
    ('Atomic Habits', 'James Clear', '978-94-0051-5970', 'paperback', 'Engels', 'Zelfontwikkeling', 'Het maakt niet uit wat je doelen zijn; dit boek geeft je een bewezen manier om jezelf – elke dag – te verbeteren. Als je het lastig vindt om je gewoontes te veranderen, ligt dat niet aan jou. Het probleem is het systeem dat je gebruikt. Slechte gewoontes blijf je herhalen niet omdat jij niet wilt veranderen, maar omdat je de verkeerde methode gebruikt. Atomic Habits biedt een bewezen methode die zorgt dat je eindelijk je gewoontes kunt aanpassen.', 'EUR 15,00', 1500, '1-2 werkdagen', 12),
    ('De meeste mensen deugen', 'Rutger Bregman', '978-90-8294-2187', 'paperback', 'Nederlands', 'Psychologie', 'Al eeuwen is de westerse cultuur doordrongen van het geloof in de verdorvenheid van de mens. Maar wat als we het al die tijd mis hadden? Rutger Bregman verweeft inzichten uit de psychologie, de economie, de biologie en de archeologie. Hij neemt je mee op een reis door de geschiedenis en geeft nieuwe antwoorden op oude vragen. Waarom veroverde juist onze soort de aarde? Hoe verklaren we onze grootste misdaden? En zijn we diep vanbinnen geneigd tot het goede of het kwade? Adembenemend, weids en revolutionair – De meeste mensen deugen herschrijft de geschiedenis en werpt nieuw licht op onze toekomst.', 'EUR 24,99', 2499, '1-2 werkdagen', 9),
    ('Socrates op sneakers', 'Elke Wiss', '978-90-2634-689-7', 'paperback', 'Nederlands', 'Filosofie', 'Met Socrates op sneakers tackelt praktisch filosoof Elke Wiss de kunst van een goed gesprek. In een tijd waarin iedereen door elkaar roeptoetert en meningen al snel dezelfde waarde als feiten krijgen, is de verbinding vaak ver te zoeken. We proberen de ander eerder te overtuigen van ons gelijk dan dat we samen op zoek gaan naar wezenlijke antwoorden. Veel van onze gesprekken hebben daardoor meer weg van een debat dan van een dialoog. We praten liever dan dat we luisteren, voor vragen stellen hebben we geen tijd. En toegeven iets niet te weten is al helemaal geen optie. Hoe mooi zou het zijn als je op elk moment en in iedere situatie weet hoe je precies díé vraag stelt die leidt tot een goed gesprek?', 'EUR 23,99', 2399, '2-3 werkdagen', 8),
    ('The Let Them Theory', 'Mel Robbins', '978-90-4393-7962', 'hardcover', 'Engels', 'Psychologie', 'Mel Robbins, wereldwijd bekend van ''De 5 Seconderegel'', introduceert in haar nieuwste boek ''The Let Them Theory'' een levensveranderend concept dat miljoenen mensen al heeft geholpen. Twee simpele woorden: Let Them, geven je de kracht om los te laten wat je niet kunt controleren en je te focussen op wat écht belangrijk is: jouw geluk, doelen en relaties.', 'EUR 23,95', 2395, '1-2 werkdagen', 11),
    ('Opgeruimd!', 'Marie Kondo', '978-94-0050-8606', 'paperback', 'Nederlands', 'Zelfontwikkeling', 'Voor altijd een schoon en rommelvrij huis: ervaar hoe opruimen je leven voorgoed kan veranderen! De Japanse Marie Kondo runt een gerenommeerd adviesbureau dat mensen leert hoe ze hun rommelige huizen kunnen transformeren in ruimtes vol rust en inspiratie. De sleutel tot succesvol opruimen is om alleen de zaken te bewaren waar je echt van houdt, en de rest weg te doen. Met een wachtlijst van drie maanden is haar KonMari-methode voor opruimen, keuzes maken en organiseren een internationaal fenomeen.', 'EUR 20,00', 2000, '1-2 werkdagen', 14),
    ('Druks', 'Francien Regelink', '978-94-6349-1181', 'paperback', 'Nederlands', 'Neurodiversiteit', 'De meeste mensen kennen ADHD als ‘Alle Dagen Heel Druk’. En druk zijn is zeker een onderdeel van de Attention Deficit Hyperactivity Disorder, maar dat is wel een héél eenzijdig beeld. Francien Regelink stelt dat beeld graag voor je bij. Want wat is ADHD eigenlijk? Wat zijn de voordelen, nadelen en de vooroordelen? Helpen pilletjes, of juist helemaal niet? Hoe zorg je dat je om kunt gaan met alle prikkels van het dagelijks leven?', 'EUR 22,99', 2299, '1-2 werkdagen', 10),
    ('Omringd met idioten', 'Thomas Erikson', '978-94-0271-8881', 'paperback', 'Nederlands', 'Psychologie', 'Heb je ooit ruzie gekregen omdat iemand je verkeerd begreep? Verbaas je je soms over het totale onvermogen van anderen om jouw punt te zien? Of heb je er genoeg van dat er niet naar je geluisterd wordt? Je bent niet de enige. Na een rampzalige ontmoeting met een succesvolle ondernemer die ervan overtuigd was dat hij werd ‘omringd door idioten’, besloot communicatie-expert Thomas Erikson onderzoek te doen naar het menselijk functioneren om antwoord te krijgen op de vraag waarom we vaak moeite hebben om met elkaar te communiceren of samen te werken.', 'EUR 15,00', 1500, '1-2 werkdagen', 15),
    ('Relativeren is ook een kunst', 'Mariëtte Baanders', '978-90-2442-6386', 'hardcover', 'Nederlands', 'Mindfulness', 'Emoties horen bij het leven. Ze geven kleur en diepgang, maar blijken soms ook ongrijpbare ‘dingen’. Terwijl we zo veel mogelijk positieve emoties najagen, brengen negatieve emoties ons flink van ons stuk. Wie wil leren om op een gezonde en constructieve manier met zijn of haar emoties om te gaan, kan aan de slag met Relativeren is ook een kunst.', 'EUR 23,50', 2350, '2-3 werkdagen', 7), 
    ('Meditations', 'Marcus Aurelius', '978-01-4044-9334', 'paperback', 'Nederlands', 'Filosofie', 'Ta eis heauton is een oorspronkelijk titelloos en in het Grieks geschreven egodocument van de Romeinse keizer Marcus Aurelius, waarin hij bondig filosofische notities heeft verzameld, die gebaseerd zijn op stoïcijnse ethiek en Marcus zijn belangrijkste overtuigingen bevatten.', 'EUR 7,99', 799, '1-2 werkdagen', 13),
    ('All About Love', 'Bell Hooks', '978-00-6095-9470', 'paperback', 'Engels', 'Relaties', 'In dit provocerende en dieppersoonlijke werk schetst bell hooks een nieuwe ethiek voor onze liefdeloze samenleving – een gepolariseerde samenleving, zo betoogt Bell Hooks, waarin het niet ontbreekt aan romantiek, maar aan zorg, mededogen en gemeenschap.', 'EUR 15,95', 1595, '1-2 werkdagen', 9),
    ('Maar je ziet er helemaal niet autistisch uit', 'Bianca Toeps', '978-946-3491-082', 'paperback', 'Nederlands', 'Neurodiversiteit', 'Autisme; da’s toch dat je heel snel lucifers kunt tellen, en weet dat 7 augustus 1984 op een dinsdag viel? Nou… Nee. Bianca Toeps legt in haar boek Maar je ziet er helemaal niet autistisch uit haarfijn uit wat het wél betekent als je autisme hebt. Op een frisse en luchtige manier beschrijft Bianca Toeps de verschillende situaties waar iemand met autisme tegenaan loopt in het dagelijks leven. Daarnaast geeft ze tips: waarom je iemand met autisme beter kunt mailen, wat je doet als iemand je liever niet aankijkt en vooral: waarom het geen compliment is als je zegt: ‘maar je ziet er helemaal niet autistisch uit!’', 'EUR 22,99', 2299, '1-2 werkdagen', 16),
    ('Existentialisme met Justin Heuvels', 'Justin Heuvels', '978-90-5000-0012-7', 'paperback', 'Nederlands', 'Filosofie', '‘Existentialisme’ komt van het Latijnse woord voor ‘bestaan’, existentia. In dit boek beschrijft Justin zijn strijd met de vraag wat het bestaan betekent. Existentialisten zoals hij geloven in de vrijheid en verantwoordelijkheid van het individu om zijn eigen leven vorm te geven. De mens moet zelf zin geven aan zijn bestaan volgens hem, in een wereld die op zichzelf betekenisloos lijkt.', 'EUR 15,99', 1599, '1-2 werkdagen', 20),
    ('De 5 talen van de liefde', 'Gary Chapman', '978-90-6353-6961', 'hardcover', 'Nederlands', 'Relaties', 'Elk mens heeft een eerste liefdestaal, een manier waarop hij of zij de liefde het best verstaat. Dit boek laat zien hoe je de eerste liefdestaal van jouw partner kunt herkennen en ontdekken. Breng al de vijf talen van liefde in praktijk en je kunt er zeker van zijn dat je partner jouw liefde voelt!', 'EUR 25,95', 2595, '2-3 werkdagen', 6),
    ('Een steekje los', 'Iris ter Haar', '978-94-6349-2713', 'paperback', 'Nederlands', 'Psychologie', 'Fris afgestudeerd psycholoog Iris ter Haar begint vol goede moed aan haar carrière als ondernemer. Voor de buitenwereld lijkt alles haar goed af te gaan, maar ongemerkt wordt haar wereld kleiner en kleiner, tot ze haar huis niet meer uit durft. Als bezigheidstherapie borduurt ze zich de blaren op de vingers terwijl ze op een eindeloos lijkende wachtlijst staat voor een psycholoog. In 2018 krijgt ze de diagnose paniekstoornis en agorafobie. Inmiddels heeft Iris een succesvolle borduurwebshop en lukt het haar (meestal) weer om zonder klamme handen de deur uit te gaan. In dit boek vertelt ze op luchtige wijze hoe het is om opgeslokt te raken door angsten tot je jezelf verliest. Maar ook hoe ze – met ups en downs – de draad weer oppakt. Inclusief handige lijstjes met wat je kunt doen als je een paniekaanval hebt, hoe je een wachtlijst doorkomt en de wetenschap achter angststoornissen.', 'EUR 22,99', 2299, '1-2 werkdagen', 10),
    ('Financial Selfcare', 'Lieke Danenberg', '978-94-0271-5996', 'paperback', 'Nederlands', 'Financien', 'Geld. We praten er liever niet over, maar we willen er allemaal genoeg van hebben. Al maakt geld niet gelukkig, het maakt het leven wel gemakkelijker. Het probleem is alleen dat veel mensen niet weten hoe ze ermee om moeten gaan. Wat is investeren? Hoe werkt beleggen? Helpt het bijhouden van een ouderwets kasboekje? Moet je bitcoins kopen? Of juist goud?', 'EUR 22,99', 2299, '1-2 werkdagen', 11),
    ('Feminisme voor ITers: waarom frontend óók bij mannen past!', 'Maaike Welles', '978-90-5000-0016-5', 'hardcover', 'Nederlands', 'Algemeen', 'Feminisme voor IT’ers: waarom frontend óók bij mannen past laat zien hoe genderstereotypen de verdeling binnen de techwereld beïnvloeden. In dit boek onderzoekt Maaike waarom frontend onterecht als “minder technisch” of vrouwelijk wordt gezien, terwijl het juist complexe en cruciale vaardigheden vereist. Vanuit een feministisch perspectief pleit ze voor het loslaten van deze labels en het waarderen van alle IT-rollen op basis van inhoud.', 'EUR 28,99', 2899, '1-2 werkdagen', 9),
    ('Tao: De levende religie van China', 'Kristofer Schipper', '978-90-2909-5396', 'hardcover', 'Nederlands', 'Filosofie', 'In Tao beschrijft de Nederlandse taoïst Kristofer Schipper in heldere taal de geschiedenis van deze Chinese leer. Hij verdiept zich in de rituelen en in de elementen waaruit de leer is opgebouwd, zoals de grote aandacht voor het menselijk lichaam en de kosmologie. Dit boeiende boek is gebaseerd op diverse taoïstische geschriften en is daardoor zowel een uitstekende inleiding voor buitenstaanders als waardevol materiaal voor wie al vertrouwd is met de filosofie van het taoïsme.', 'EUR 29,95', 2995, '1-2 werkdagen', 14),
    ('Wanneer je lichaam nee zegt', 'Gabor Mate', '978-90-2021-6820', 'paperback', 'Nederlands', 'Gezondheid', 'Gebaseerd op wetenschappelijk onderzoek en aan de hand van vele voorbeelden en verhalen uit zijn eigen huisartsenpraktijk en zijn werk in de palliatieve en verslavingszorg, geeft Maté antwoord op vragen over de rol die de mind-bodyconnectie speelt in het ontwikkelen van lichamelijke en geestelijke ziektes. Hij geeft overtuigend bewijs voor deze link en laat bovenal zien dat wij allemaal de wijsheid bezitten om onszelf te helen. Met Wanneer je lichaam nee zegt kan ieder van ons zich afstemmen op de innerlijke wijsheid die we allemaal bezitten.', 'EUR 22,50', 2250, '2-3 werkdagen', 8),
    ('Rustig slapen', 'Ingrid Verbeek', '978-90-2446-3961', 'paperback', 'Nederlands', 'Gezondheid', 'Verbeek geeft advies voor een goede nachtrust in iedere levensfase. Aan slechte slapers die beter willen slapen en aan goede slapers die goed willen blijven slapen. Dit doet zij aan de hand van informatie over slaap, concrete opdrachten, persoonlijke verhalen en voorbeelden van mensen die zij in haar praktijk tegenkwam.', 'EUR 23,50', 2350, '1-2 werkdagen', 17),
    ('Ontdek de kracht van ademen', 'Rob Koning', '978-90-4392-7932', 'paperback', 'Nederlands', 'Mindfulness', 'Mr. Breath laat zien hoe je volledig gebruik kunt maken van je longcapaciteit. Je leert o.a. over de relatie tussen ademhaling en burn-out en hoe je door bewuste ademhaling kunt zorgen voor meer vitaliteit, meer ontspanning en een leeg hoofd. Met een vrije doorstroming van de adem kun je gezonder en energieker leven, beter ontspannen en je eigen grenzen bepalen.', 'EUR 24,99', 2499, '1-2 werkdagen', 18),
    ('Houd me vast', 'Sue Johnson', '978-90-2156-5231', 'paperback', 'Nederlands', 'Relaties', 'Dr. Sue Johnson is klinisch psycholoog en een vooraanstaand deskundige in de relatiewetenschap. Tevens ontwikkelaar van Emotionally Focused Couple Therapy. In Houd me vast maakt Sue Johnson de lezer deelgenoot van haar baanbrekende en buitengewoon succesvolle programma voor het creëren van hechte en veilige relaties.', 'EUR 28,75', 2875, '1-2 werkdagen', 12),
    ('Own the Room', 'Pauline Pater', '978-90-4394-0191', 'paperback', 'Nederlands', 'Zelfontwikkeling', 'Zeg vaarwel tegen twijfels, pak angsten bij de lurven en laat jezelf zien. Met Own the Room leert de lezer zijn of haar plek in te nemen op het werk, op het podium, en in zijn eigen leven. Het praktische boek van trainer en spreker Pauline Pater staat vol herkenbare verhalen, oefeningen en toepasbare tips. Pauline Pater geeft iedereen het zelfvertrouwen om te kiezen voor wat hij echt wil en zich niet langer te laten afleiden door de meningen van anderen.', 'EUR 21,99', 2199, '1-2 werkdagen', 13),
    ('Tel tot 10 met Pieter Kok', 'Pieter Kok', '978-90-5000-0023-3', 'paperback', 'Nederlands', 'Algemeen', 'De basis van de wiskunde onder de knie krijgen was nog nooit zo leuk! Pieter Kok helpt iedereen op een speelse manier cijfers te herkennen en te tellen, ongeacht achtergrond of huidige rekenvaardigheden.', 'EUR 17,25', 1725, '1-2 werkdagen', 11),
    ('Gezond(er) met dokter Elise', 'Elise Janssen', '978-90-6222-4586', 'hardcover', 'Nederlands', 'Gezondheid', 'Huisarts Elise Janssen krijgt in de spreekkamer dagelijks vragen over voeding en gezondheid. Geïnspireerd door de vele patiënten met leefstijlgerelateerde aandoeningen, creëerde ze een succesvol Instagram-account en inspireert ze inmiddels meer dan 134.000 volgers om te werken aan een gezondere leefstijl. Door het ontkrachten van gezondheidsmythes, het vertalen van gefundeerde medische kennis naar dagelijkse praktische tips én het delen van makkelijke VEVO-proof recepten (VEVO staat voor: Vitamines, Eiwitten, Vezels en Onverzadigde vetten) leert ze je om stap voor stap je eigen gezondheid te verbeteren.', 'EUR 26,95', 2695, '2-3 werkdagen', 7),
    ('Eetgestoord', 'Charlotte Simons', '978-94-6349-3765', 'paperback', 'Nederlands', 'Gezondheid', 'Charlotte Simons kreeg boulimia nervosa toen ze pas twaalf jaar oud was. Ruim achttien jaar later is ze grotendeels hersteld, maar voor haar gevoel zal ze altijd met één voet in de parallelle wereld van haar eetstoornis blijven staan. In dit boek vertelt ze zonder schroom over haar diagnose, geeft ze haar kritische kijk op de huidige hulpverlening en beschrijft ze de lange weg naar haar herstel. Ook bespreekt ze de andere vormen die deze ziekte kent door in gesprek te gaan met ervaringsdeskundigen en specialisten.', 'EUR 22,99', 2299, '1-2 werkdagen', 10),
    ('Wees eens lief voor jezelf', 'Maaret Kallio', '978-94-0051-5123', 'paperback', 'Nederlands', 'Mindfulness', 'Uit het land met de gelukkigste inwoners ter wereld komt dit praktische en compassievolle boek. Het is geen standaard zelfhulpboek. Kallio belooft je geen kant-en-klaar geluk, geen nieuwe en betere versie van jezelf, of een fantastisch leven. Maar wél inzichten en concrete handvatten waarmee je kunt werken aan een duurzamere en sterkere versie van jezelf. We moeten ons toestaan alle emoties te voelen die bij het leven horen: blijdschap, enthousiasme, teleurstelling, verdriet… Dit is de enige manier om geluk te vinden. Door je eigen leven onder de loep te nemen zul je zien wat jou geluk brengt en kun je van daaruit een zingevend leven leiden.', 'EUR 22,99', 2299, '1-2 werkdagen', 16),
    ('Anders gaat ook', 'Elise Cordaro', '978-90-8924-7117', 'paperback', 'Nederlands', 'Neurodiversiteit', 'In dit boek spreekt Elise openhartig over hoe ze omgaat met haar dubbele diagnose. Ze gunt ons een blik in haar belevingswereld en steekt lotgenoten een hart onder de riem met concrete tips, mind hacks en inspiratie om beter te functioneren met autisme en ADHD.', 'EUR 17,99', 1799, '1-2 werkdagen', 19),
    ('Spreken in het openbaar', 'Wim Daniëls', '978-90-2446-4319', 'paperback', 'Nederlands', 'Psychologie', 'Dit boek is voor alle mensen die weleens in een situatie terechtkomen – en voor wie geldt dat niet – waarin ze ten overstaan van een groep het woord moeten voeren. Voor de professional die beroepsmatig veel voordrachten houdt, maar ook voor de incidentele spreker die het woord moet nemen. Bijvoorbeeld op een bruiloft, een ouderavond, tijdens een vergadering, in een teambijeenkomst of bij een jubileum. Na het lezen van Spreken in het openbaar spreekt iedereen met plezier voor een publiek.', 'EUR 21,25', 2125, '1-2 werkdagen', 12),
    ('Schat, kunnen we eens praten?', 'Tim Verleyzen', '978-94-0143-5864', 'paperback', 'Nederlands', 'Relaties', 'Relatie-expert Tim Verleyzen deelt in zijn boek realistische casestudys, verhelderende inzichten en concrete handvatten die je meteen kunt toepassen. Zet in op een diepere verbinding, ervaar minder conflicten en ontdek hoe je samen betere gesprekken voert.', 'EUR 22,99', 2299, '1-2 werkdagen', 9),
    ('Gun iedere kabouter zijn eigen muts', 'Aaf Brandt Corstius', '978-90-2909-9158', 'paperback', 'Nederlands', 'Algemeen', 'Aaf noteert elk verstandig zinnetje in haar notitieblok, om later op te schrijven hoe ze het zelf toepast in haar leven. En hoe het misschien wel behulpzaam kan zijn in ieders bestaan. Want wie wil nou niet weten wat een honderdjarige je na een eeuw aan ervaring met klem zou aanraden, wat het ezelsbruggetje is bij grote beslissingen die onmogelijk te nemen lijken, of met welke uitspraak je je altijd kunt onttrekken aan irritante groepsactiviteiten? Dit boek staat vol verhalen over deze wijze zinnen, verzameld door jaren goed opletten. Ook over die kabouter en zijn muts.', 'EUR 17,50', 1750, '1-2 werkdagen', 8),
    ('Tel tot 10 met Pieter Kok (Kindereditie)', 'Pieter Kok', '978-90-5000-0031-8', 'hardcover', 'Nederlands', 'Algemeen', 'De basis van de wiskunde onder de knie krijgen was nog nooit zo leuk! Dit boek helpt kinderen op een speelse manier cijfers te herkennen en te tellen. De kindereditie bevat leuke illustraties en interactieve elementen.', 'EUR 24,50', 2450, '2-3 werkdagen', 6),
    ('Asociale media', 'Thijs Launspach', '978-90-0038-7236', 'paperback', 'Nederlands', 'Algemeen', 'In Asociale media onderzoekt psycholoog Thijs Launspach (bekend van bestsellers als Fokking druk en Je bent al genoeg) de invloed van sociale media op onze mentale gezondheid. Hij legt bloot welk spel er wordt gespeeld, en laat zien wat je zelf kunt doen om je aan de macht van de socials te ontworstelen.', 'EUR 17,99', 1799, '1-2 werkdagen', 14),
    ('Nooit meer piekeren', 'Marleen Derks', '978-94-9249-5884', 'paperback', 'Nederlands', 'Zelfontwikkeling', 'Nooit meer piekeren leert je om jezelf te begrijpen, je eigen capaciteiten beter te gebruiken, te zien wat belangrijk voor je is en op jezelf te vertrouwen. Dit boek levert in de eerste plaats inzicht in je eigen gedachten, gevoelens en gedragspatronen. Als je weet hoe piekergedrag werkt, kun je het veranderen. Inzicht is al genoeg om de verandering in werking te stellen. Met de oefeningen en adviezen in dit boek, kun je jezelf met succes ontpiekeren. ', 'EUR 19,95', 1995, '1-2 werkdagen', 13),
    ('Elke dag om 15.00 uur klaar', 'Björn Deusings', '978-90-2158-2382', 'paperback', 'Nederlands', 'Zelfontwikkeling', 'Een 6-urige werkdag klinkt misschien te mooi om waar te zijn. Dat is het echter niet. Als je jezelf beter organiseert, realistischer plant, op een slimme manier omgaat met complexe taken en ophoudt met jezelf (en anderen) van het werk te houden, dan is het heel goed mogelijk om veel tijd te besparen. Praktisch toepasbaar en toegankelijk geschreven door de meest toonaangevende opleider op het gebied van slimmer werken.', 'EUR 24,99', 2499, '1-2 werkdagen', 15),
    ('Reflecteren: de basis', 'Mirjam Groen', '978-90-0107-9369', 'paperback', 'Nederlands', 'Zelfontwikkeling', 'De essentie van het reflecteren is het nadenken over het eigen (professioneel) handelen om dit vervolgens te kunnen optimaliseren. Met behulp van Reflecteren: de basis leer je reflectievaardigheden te ontwikkelen aan de hand van voorbeelden, voorbeeldgedrag en oefeningen.', 'EUR 46,75', 4675, '1-2 werkdagen', 12),
    ('Ga gewoon wat leuks doen', 'Aafke Romeijn', '978-94-6349-321-5', 'paperback', 'Nederlands', 'Psychologie', 'In Ga gewoon wat leuks doen vertelt Aafke hoe een (leven met) depressie eruitziet, wat de oorzaken kunnen zijn en hoe je er weer vanaf kunt komen – en waarom dat eigenlijk nooit ‘gewoon iets leuks gaan doen’ is. Aafke schrijft openhartig over haar lange zoektocht naar de diagnose, de verschillende vormen van therapie, haar wisselende ervaringen met de ggz en (de bijwerkingen van) haar medicatiegebruik. Ook schuwt ze taboeonderwerpen als het effect van haar depressies op haar seksleven, zwangerschap en moederschap niet.', 'EUR 22,99', 2299, '1-2 werkdagen', 10),
    ('Gezonde routines', 'Arie Boomsma', '978-90-4464-8096', 'hardcover', 'Nederlands', 'Gezondheid', 'In Gezonde routines deelt Arie Boomsma de vijftig allerbeste tips voor een fit en vitaal leven. Geen strakke regimes en strenge diëten, maar kleine, haalbare stappen.', 'EUR 22,25', 2225, '2-3 werkdagen', 8),
    ('Master Your Mindset', 'Michael Pilarczyk', '978-90-7967-9669', 'hardcover', 'Nederlands', 'Zelfontwikkeling', 'Master Your Mindset gaat over persoonlijke en spirituele groei, maar ook over zakelijk succes. Die combinatie maakt dit boek uniek. Michael Pilarczyk schreef op basis van zijn eigen ervaringen een persoonlijk verhaal over bewustzijn, zingeving en inzicht. Het boek gaat over het begrijpen van je eigen denkwijze (mindset) en hoe je die effectief kunt veranderen om de kwaliteit van je leven te verbeteren. Hoe ziet jouw mooiste leven eruit. Heb je daar wel eens over nagedacht? Wat wil je écht? Ontdek je mogelijkheden, haal het beste uit jezelf en maak je dromen waar. ', 'EUR 38,40', 3840, '1-2 werkdagen', 11),
    ('Gevalletje borderline', 'Kathelijn Hulshof', '978-94-6349-227-0', 'paperback', 'Nederlands', 'Neurodiversiteit', 'Gevalletje borderline is een emotioneel, aangrijpend boek over borderline en hoe het is om ermee te leven. Het is een rauw verhaal over het ontstaan van deze stoornis, de diagnose, de verschillende therapieën die er zijn en welke invloed het heeft op je omgeving. Kathelijn verweeft haar eigen ervaring met de medische en psychische aspecten, waardoor Gevalletje borderline binnenkomt als een mokerslag en voor veel begrip zal zorgen bij iedereen die het leest.', 'EUR 22,99', 2299, '1-2 werkdagen', 9),
    ('We doen allemaal maar wat', 'Thijs Launspach', '978-90-0038-7182', 'paperback', 'Nederlands', 'Psychologie', 'In dit boek verkent psycholoog en bestsellerauteur Thijs Launspach de belangrijkste lessen die we uit de psychologie kunnen trekken. Een boek voor iedereen die meer wil weten over de wetenschap van ons brein, onze mind en ons gedrag. De psychologie leert ons met meer begrip te kijken naar anderen en naar onszelf – onmisbaar in de verwarrende tijden waar we momenteel in leven.', 'EUR 19,95', 1995, '1-2 werkdagen', 10)
